deluge_script:
if(input.Company == null)
										{
											alert "Company is required.";
											cancel submit;
										}
										if(input.Invoice_Date == null)
										{
											alert "Invoice Date is required.";
											cancel submit;
										}
										if(input.Invoice_Number == null || input.Invoice_Number.trim() == "")
										{
											alert "Invoice Number is required.";
											cancel submit;
										}
										if(input.Customer == null)
										{
											alert "Customer is required.";
											cancel submit;
										}
										//====================================================
										//INVOICE NUMBER
										//====================================================
										if(input.Company != null && isNull(input.Invoice_Number))
										{
											docKey = Document_Key[Voucher_Type == "Invoice" && Document_Key_Status == "Active"];
											if(docKey.ID != null)
											{
												vno = employee_management.Generate_Voucher_Number(docKey.ID);
												if(vno != null && vno != "" && vno != "LIMIT_REACHED")
												{
													input.Invoice_Number = vno;
												}
												else if(vno == "LIMIT_REACHED")
												{
													alert "Invoice number limit reached.";
												}
												else
												{
													alert "Unable to generate Invoice Number.";
												}
											}
											else
											{
												alert "No active Document Key found for Invoice.";
											}
										}

u = thisapp.audit.getLoginAuditInfo();
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;

u = thisapp.audit.getLoginAuditInfo();
										input.Updated_By_Name = u.get("name");
										input.Updated_By_Email = u.get("email");
										input.Updated_By_Time = zoho.currenttime;

hide Display_Name_Customer;
										hide Display_Name_Company;
										hide Discount_Amount;
										hide Discount_Percentage;
										hide Reason_Why_Cancelled;
										hide Fiscal_Document_Number;
										hide Date_Sent;
										disable Sub_Total;
										disable Grand_Total;
										disable Amount_Paid;
										disable Balance_Due;
										disable Invoice_Status;
										disable Payment_Status;
										disable Date_Sent;
										//disable Invoice_Number;
										if(input.Send_Invoice == true)
										{
											show Fiscal_Document_Number;
											show Date_Sent;
										}
										else
										{
											hide Fiscal_Document_Number;
											hide Date_Sent;
										}
										if(input.ID != null)
										{
											disable Company;
											disable Invoice_Date;
											disable Customer;
											disable Invoice_Number;
											disable Tax_Amount;
										}
										//disable Details.Tax_Type;
										disable Details.Tax_Amount;
										disable Details.Employee_Voucher;
										disable Details.Display_Name_Voucher;
										disable Details.Line_Number;
										disable Details.Item;
										disable Details.Details;
										disable Details.Quantity;
										disable Details.Site;
										disable Details.Account;
										disable Details.Rate;
										hide Details.Display_Name_Employee_Voucher;
										hide Details.Details_Date;
										hide Details.Lease;
										hide Details.Sales_Voucher;
										hide Details.Group;
										hide Details.Invoice_Details_Status;
										hide Details.Source_Record_ID;
										hide Details.Source_Form;
										hide Details.Last_Synced_Group_Amount;
										hide Details.Last_Synced_Group_ID;
										hide Details.Display_Name_Invoice;
										hide Details.Display_Name_Group;
										hide Details.User_Name;
										hide Details.User_Email;
										hide Details.User_Role;
										hide Details.Created_By_Name;
										hide Details.Created_By_Email;
										hide Details.Created_By_Time;
										hide Details.Updated_By_Name;
										hide Details.Updated_By_Email;
										hide Details.Updated_By_Time;
										hide Payment_Received_Details.Display_Name_Voucher;
										hide Payment_Received_Details.Sales_Voucher;
										hide Payment_Received_Details.Credit_Note_Voucher;
										hide Payment_Received_Details.Display_Name_Invoice_Voucher;
										hide Payment_Received_Details.Amount_Credited;
										hide Payment_Received_Details.Payment_Type;
										hide Payment_Received_Details.Customer_Deposit_Voucher;
										hide Payment_Received_Details.Customer_Deposit_Number;
										hide Payment_Received_Details.Payment_Document;
										hide Payment_Received_Details.Amount_Not_Allocated;
										hide Payment_Received_Details.User_Name;
										hide Payment_Received_Details.User_Email;
										hide Payment_Received_Details.User_Role;
										hide Payment_Received_Details.Created_By_Name;
										hide Payment_Received_Details.Created_By_Email;
										hide Payment_Received_Details.Created_By_Time;
										hide Payment_Received_Details.Updated_By_Name;
										hide Payment_Received_Details.Updated_By_Email;
										hide Payment_Received_Details.Updated_By_Time;
										hide Back_End;
										u = thisapp.audit.getLoginAuditInfo();
										input.User_Name = u.get("name");
										input.User_Email = u.get("email");
										input.User_Role = u.get("role");
										hide Services.Display_Name_Service;
										hide Services.Bill;
										// ==============================
										// SERVICES SUBFORM - BACK END
										// ==============================
										hide Services.Display_Name_Voucher;
										hide Services.Display_Name_Bill;
										hide Services.User_Name;
										hide Services.User_Email;
										hide Services.User_Role;
										hide Services.Created_By_Name;
										hide Services.Created_By_Email;
										hide Services.Created_By_Time;
										hide Services.Updated_By_Name;
										hide Services.Updated_By_Email;
										hide Services.Updated_By_Time;
										// ==============================
										// BILL SUBFORM - HIDE USER FIELDS
										// ==============================
										hide Bill.Employee_Vendor;
										hide Bill.Sales_Voucher;
										hide Bill.Customer;
										hide Bill.Services_Total;
										hide Bill.Total_Amount;
										hide Bill.Tax_Amount;
										hide Bill.Discount_Amount;
										hide Bill.Amount_Due;
										hide Bill.Amount_Paid;
										hide Bill.Balance_Due;
										hide Bill.Display_Name_Vendor;
										hide Bill.Bill_Type;
										hide Bill.User_Name;
										hide Bill.User_Email;
										hide Bill.User_Role;
										hide Bill.Created_By_Name;
										hide Bill.Created_By_Email;
										hide Bill.Created_By_Time;
										hide Bill.Updated_By_Name;
										hide Bill.Updated_By_Email;
										hide Bill.Updated_By_Time;

if(input.Cancel_Invoice == true)
										{
											show Reason_Why_Cancelled;
										}
										else
										{
											hide Reason_Why_Cancelled;
											input.Reason_Why_Cancelled = "";
										}

if(input.Company != null)
										{
											input.Display_Name_Company = input.Company.Company_Name;
										}
										else
										{
											input.Display_Name_Company = "";
										}

if(input.Discount_Amount == null)
										{
											input.Discount_Amount = 0;
										}
										if(input.Discount_Amount > ifnull(input.Sub_Total,0))
										{
											alert "Discount Amount cannot be greater than Sub Total.";
											input.Discount_Amount = ifnull(input.Sub_Total,0);
										}
										input.Grand_Total = ifnull(input.Sub_Total,0) + ifnull(input.Tax_Amount,0) - ifnull(input.Discount_Amount,0);
										input.Balance_Due = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);

if(input.Discount_Percentage == null)
										{
											input.Discount_Percentage = 0;
										}
										if(input.Discount_Percentage > 100)
										{
											alert "Discount Percentage cannot be greater than 100%.";
											input.Discount_Percentage = 100;
										}
										discount_amt = ifnull(input.Sub_Total,0) * ifnull(input.Discount_Percentage,0) / 100;
										input.Discount_Amount = discount_amt;
										input.Grand_Total = ifnull(input.Sub_Total,0) + ifnull(input.Tax_Amount,0) - discount_amt;
										input.Balance_Due = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);

if(input.Discount_Type == "None")
										{
											hide Discount_Percentage;
											hide Discount_Amount;
											input.Discount_Percentage = 0;
											input.Discount_Amount = 0;
										}
										else if(input.Discount_Type == "Percentage")
										{
											show Discount_Percentage;
											hide Discount_Amount;
											input.Discount_Amount = 0;
										}
										else if(input.Discount_Type == "Amount")
										{
											hide Discount_Percentage;
											show Discount_Amount;
											input.Discount_Percentage = 0;
										}

if(input.Send_Invoice == true)
										{
											show Fiscal_Document_Number;
											show Date_Sent;
										}
										else
										{
											hide Fiscal_Document_Number;
											hide Date_Sent;
											input.Fiscal_Document_Number = "";
											input.Date_Sent = null;
										}

if(row.Service != null)
										{
											row.Display_Name_Service=row.Service.Service_Name;
										}
										else
										{
											row.Display_Name_Service="";
										}

sub_total = ifnull(input.Sub_Total,0.0);
										discount = ifnull(input.Discount_Amount,0.0);
										grand_total = sub_total - discount + ifnull(input.Tax_Amount,0.0);
										input.Grand_Total = grand_total;
										input.Balance_Due = grand_total - ifnull(input.Amount_Paid,0.0);

if(input.Company == null)
										{
											alert "Company is required.";
											cancel submit;
										}
										if(input.Invoice_Date == null)
										{
											alert "Invoice Date is required.";
											cancel submit;
										}
										if(input.Invoice_Number == null || input.Invoice_Number.trim() == "")
										{
											alert "Invoice Number is required.";
											cancel submit;
										}
										if(input.Customer == null)
										{
											alert "Customer is required.";
											cancel submit;
										}
										if(input.Send_Invoice == true && input.Cancel_Invoice == true)
										{
											alert "An Invoice cannot be Sent and Cancelled at the same time.";
											cancel submit;
										}
										if(input.Send_Invoice == true && input.Fiscal_Document_Number == null || input.Fiscal_Document_Number.trim() == "")
										{
											alert "FD Number is required When Sending an Invoice.";
											cancel submit;
										}
										if(input.Cancel_Invoice == true && input.Reason_Why_Cancelled == null || input.Reason_Why_Cancelled.trim() == "")
										{
											alert "Reason Why Cancelled is required When Cancelling an Invoice.";
											cancel submit;
										}

if(input.Cancel_Invoice == true)
										{
											input.Invoice_Status = "Cancelled";
										}
										else if(input.Send_Invoice == true)
										{
											input.Invoice_Status = "Invoiced";
											if(input.Date_Sent == null)
											{
												input.Date_Sent = zoho.currentdate;
											}
										}
										else
										{
											input.Invoice_Status = "Draft";
										}
										// =====================================================
										// INVOICE FINALIZATION
										// =====================================================
										sub_total = 0.0;
										total_tax = 0.0;
										// =====================================================
										// 1. TOTAL INVOICE DETAILS
										// =====================================================
										detail_rows = Invoice_Details[Invoice == input.ID];
										for each  detail_rec in detail_rows
										{
											line_total = round(ifnull(detail_rec.Line_Total,0.0),2);
											line_tax = round(ifnull(detail_rec.Tax_Amount,0.0),2);
											sub_total = sub_total + line_total;
											total_tax = total_tax + line_tax;
											if(input.Invoice_Number != null && input.Invoice_Number.trim() != "")
											{
												detail_rec.Display_Name_Invoice=input.Invoice_Number;
											}
											detail_rec.Invoice_Details_Status="Invoiced";
										}
										// =====================================================
										// 2. TOTAL SERVICES
										// =====================================================
										for each  service_row in input.Services
										{
											if(input.Invoice_Number != null && input.Invoice_Number.trim() != "")
											{
												service_row.Display_Name_Voucher=input.Invoice_Number;
											}
											service_line_total = round(ifnull(service_row.Line_Total,0.0),2);
											sub_total = sub_total + service_line_total;
										}
										sub_total = round(sub_total,2);
										total_tax = round(total_tax,2);
										discount_type = ifnull(input.Discount_Type,"").trim();
										discount_amount = 0.0;
										if(discount_type == "Percentage")
										{
											discount_percentage = round(ifnull(input.Discount_Percentage,0.0),2);
											discount_amount = round(sub_total * discount_percentage / 100,2);
										}
										else if(discount_type == "Amount")
										{
											discount_amount = round(ifnull(input.Discount_Amount,0.0),2);
										}
										else
										{
											discount_amount = 0.0;
											input.Discount_Percentage = 0.0;
										}
										if(discount_amount > sub_total)
										{
											discount_amount = sub_total;
										}
										if(discount_amount < 0)
										{
											discount_amount = 0.0;
										}
										input.Discount_Amount = discount_amount;
										grand_total = round(sub_total - discount_amount + total_tax,2);
										if(grand_total < 0)
										{
											grand_total = 0.0;
										}
										amount_paid = round(ifnull(input.Amount_Paid,0.0),2);
										balance_due = round(grand_total - amount_paid,2);
										if(balance_due < 0)
										{
											balance_due = 0.0;
										}
										input.Sub_Total = sub_total;
										input.Tax_Amount = total_tax;
										input.Grand_Total = grand_total;
										input.Balance_Due = balance_due;
										if(amount_paid <= 0)
										{
											input.Payment_Status = "Not Paid";
										}
										else if(balance_due > 0)
										{
											input.Payment_Status = "Partially Paid";
										}
										else
										{
											input.Payment_Status = "Paid";
										}

if(input.Sales_Voucher_Date == null)
										{
											input.Sales_Voucher_Date = zoho.currentdate;
										}
										if(input.Sales_Voucher_Number == null || input.Sales_Voucher_Number == "")
										{
											doc = Document_Key[Voucher_Type == "Sales Voucher" && Document_Key_Status == "Active"];
											if(doc.ID == null)
											{
												alert "No active Document Key found for Sales Voucher.";
												cancel submit;
											}
											next_no = ifnull(doc.Next_Number,1);
											if(next_no < 10)
											{
												num_txt = "0000" + next_no;
											}
											else if(next_no < 100)
											{
												num_txt = "000" + next_no;
											}
											else if(next_no < 1000)
											{
												num_txt = "00" + next_no;
											}
											else if(next_no < 10000)
											{
												num_txt = "0" + next_no;
											}
											else
											{
												num_txt = "" + next_no;
											}
											input.Sales_Voucher_Number = doc.Prefix + "-" + num_txt;
											doc.Next_Number=next_no + 1;
										}
										for each  row in input.Product_Details
										{
											row.Display_Name_Sales_Voucher=input.Sales_Voucher_Number;
										}
										//===================================================
										// GENERATION OF CARD NUMBERS
										//===================================================
										if(input.Sales_Type == "Sand Sales" && input.Card_Number == null || input.Card_Number == "")
										{
											seq = Sequences[Sequence_Key == "CB" && Is_Active == true];
											if(seq.ID == null)
											{
												alert "CBsequence not found.";
												cancel submit;
											}
											next_no = ifnull(seq.Next_Number,1);
											if(next_no > ifnull(seq.Max_Number,999))
											{
												alert "CB sequence has reached the maximum number (999).";
												cancel submit;
											}
											if(next_no < 10)
											{
												num = "00" + next_no;
											}
											else if(next_no < 100)
											{
												num = "0" + next_no;
											}
											else
											{
												num = "" + next_no;
											}
											input.Card_Number = "CB" + num;
											seq.Next_Number=next_no + 1;
										}

// =====================================================
										// HIDE DISPLAY FIELDS
										// =====================================================
										hide Display_Name_Vendor;
										hide Services.Display_Name_Voucher;
										hide Services.Display_Name_Service;
										hide Bill_Details.Display_Name_Bill;
										hide Bill_Details.Display_Name_Item;
										hide Bill_Details.Display_Name_Unit_Of_Measure;
										hide Payment_Made_Details.Display_Name_Bill;
										hide Payment_Made_Details.Display_Name_Payment_Made_Voucher;
										hide Payment_Made_Details.Display_Name_Vendor;
										// =====================================================
										// SHOW / HIDE MAIN SECTIONS
										// =====================================================
										hide Customer;
										hide Vendor;
										if(input.ID == null)
										{
											hide Services;
										}
										else
										{
											show Services;
										}
										// =====================================================
										// BACK END
										// =====================================================
										hide Back_End;
										disable User_Name;
										disable User_Email;
										disable User_Role;
										disable Created_By_Name;
										disable Created_By_Email;
										disable Created_By_Time;
										disable Updated_By_Name;
										disable Updated_By_Email;
										disable Updated_By_Time;
										// Logged-in user
										u = thisapp.audit.getLoginAuditInfo();
										input.User_Name = u.get("name");
										input.User_Email = u.get("email");
										input.User_Role = u.get("role");
										// =====================================================
										// BILL TYPE
										// =====================================================
										hide Vendor;
										hide Customer;
										hide Employee_Vendor;
										hide Sales_Voucher;
										hide Invoice;
										if(input.Bill_Type == "Store Bill")
										{
											show Vendor;
										}
										else if(input.Bill_Type == "Employee Bill")
										{
											show Employee_Vendor;
										}
										else if(input.Bill_Type == "Sales Voucher Bill")
										{
											show Customer;
											show Sales_Voucher;
										}
										if(input.Bill_Type == "Invoice Bill")
										{
											disable Bill_Name;
											disable Bill_Number;
										}
										if(input.Bill_Type == "Sales Voucher Bill")
										{
											disable Bill_Name;
											disable Bill_Number;
										}
										else
										{
											enable Bill_Name;
											enable Bill_Number;
										}
										disable Services_Total;
										disable Total_Amount;
										disable Tax_Amount;
										disable Discount_Amount;
										disable Amount_Due;
										disable Amount_Paid;
										disable Balance_Due;
										disable Bill_Status;
										disable Payment_Status;
										// =====================================================
										// SERVICES SUBFORM
										// =====================================================
										disable Services.Service;
										disable Services.Description;
										disable Services.Quantity;
										disable Services.Rate;
										hide Services.Invoice;
										hide Services.Last_Synced_Group_ID;
										hide Services.Last_Synced_Group_Amount;
										hide Services.Created_By_Name;
										hide Services.Created_By_Email;
										hide Services.Created_By_Time;
										hide Services.Updated_By_Name;
										hide Services.Updated_By_Email;
										hide Services.Updated_By_Time;
										hide Services.User_Name;
										hide Services.User_Email;
										hide Services.User_Role;
										// =====================================================
										// PAYMENT MADE DETAILS SUBFORM
										// =====================================================
										hide Payment_Made_Details.Payment_Type;
										hide Payment_Made_Details.Amount_Not_Allocated;
										hide Payment_Made_Details.Created_By_Name;
										hide Payment_Made_Details.Created_By_Email;
										hide Payment_Made_Details.Created_By_Time;
										hide Payment_Made_Details.Updated_By_Name;
										hide Payment_Made_Details.Updated_By_Email;
										hide Payment_Made_Details.Updated_By_Time;
										hide Payment_Made_Details.User_Name;
										hide Payment_Made_Details.User_Email;
										hide Payment_Made_Details.User_Role;
										disable Payment_Made_Details.Payment_Made_Voucher;
										disable Payment_Made_Details.Line_Number;
										disable Payment_Made_Details.Payment_Document;
										disable Payment_Made_Details.Amount_Due;
										disable Payment_Made_Details.Amount_Allocated;
										disable Payment_Made_Details.Amount_Paid;
										disable Payment_Made_Details.Balance_Due;

u = thisapp.audit.getLoginAuditInfo();
										input.Created_By_Name = u.get("name");
										input.Created_By_Email = u.get("email");
										input.Created_By_Time = zoho.currenttime;

u = thisapp.audit.getLoginAuditInfo();
										input.Updated_By_Name = u.get("name");
										input.Updated_By_Email = u.get("email");
										input.Updated_By_Time = zoho.currenttime;

if(input.Bill_Type == "Store Bill")
										{
											show Vendor;
											hide Employee_Vendor;
											hide Sales_Voucher;
											hide Customer;
											hide Invoice;
											hide Display_Name_Vendor;
											input.Employee_Vendor = null;
											input.Sales_Voucher = null;
											input.Customer = null;
											input.Invoice = null;
											input.Display_Name_Vendor = "";
										}
										else if(input.Bill_Type == "Employee Bill")
										{
											hide Vendor;
											show Employee_Vendor;
											hide Sales_Voucher;
											hide Customer;
											hide Invoice;
											hide Display_Name_Vendor;
											input.Vendor = null;
											input.Customer = null;
											input.Invoice = null;
											input.Sales_Voucher = null;
										}
										else if(input.Bill_Type == "Invoice Bill")
										{
											show Invoice;
											hide Employee_Vendor;
											show Vendor;
											hide Sales_Voucher;
											hide Display_Name_Vendor;
											input.Vendor = null;
											input.Employee_Vendor = null;
											input.Display_Name_Vendor = "";
										}
