										// =====================================================
										// INTERNAL TRANSFER QUANTITY SAFETY
										// =====================================================
										if(input.Receiving_Type == "Internal Transfer" && input.Transfer_Item != null && input.Quantity_Received != null && input.Quantity_Received > 0)
										{
											quantity_sent = ifnull(input.Transfer_Item.Quantity,0.0);
											quantity_already_received = ifnull(input.Transfer_Item.Quantity_Received,0.0);
											quantity_remaining = quantity_sent - quantity_already_received;
											if(quantity_remaining < 0)
											{
												quantity_remaining = 0.0;
											}
											if(input.Quantity_Received > quantity_remaining)
											{
