										// LINE TOTAL
										// =====================================================
										if(input.Quantity_Received != null && input.Quantity_Received > 0 && input.Rate != null && input.Rate >= 0)
										{
											input.Line_Total = (input.Quantity_Received * input.Rate).round(2);
