										else
										{
											input.Line_Total = null;
										}

// =======================================
										// STOCK RECEIVING DETAILS - FULL VALIDATION
										// =======================================
										errors = List();
										rtype = ifnull(input.Receiving_Type,"").trim();
										stock_cond = ifnull(input.Stock_Condition,"").trim();
										qty_received = ifnull(input.Quantity_Received,0.0);
										old_rec = null;
										if(input.ID != null)
