											errors.add("• Stock Receiving Voucher Number is required.");
										}
										if(input.Stock_Receiving_Voucher != null && input.Stock_Receiving_Voucher_Number != null)
										{
											dup = Stock_Receiving_Details[Stock_Receiving_Voucher == input.Stock_Receiving_Voucher && Stock_Receiving_Voucher_Number == input.Stock_Receiving_Voucher_Number && ID != input.ID];
