											errors.add("• Stock Condition is required.");
										}
										if(qty_received <= 0)
										{
											errors.add("• Quantity Received must be greater than zero.");
										}
										if(input.Unit_Of_Measure_Received == null)
										{
											errors.add("• Unit Of Measure Received is required.");
										}
										actual_item_id = null;
										actual_item_rec = null;
										po_det = null;
										issue_rec = null;
										selected_issue_id = null;
										// =======================================
										// RECEIVING TYPE VALIDATION
										// =======================================
										if(rtype == "Purchase Order")
										{
											if(input.Purchase_Order == null)
											{
												errors.add("• Purchase Order is required.");
											}
											else if(input.Item == null)
											{
												errors.add("• Purchase Order line Item is required.");
											}
											else
											{
												po_det = Purchase_Order_Details[ID == input.Item];
												if(po_det.ID == null || po_det.Item == null)
												{
													errors.add("• The selected Purchase Order line is invalid.");
												}
												else
												{
													actual_item_id = po_det.Item;
													po_stock_cond = ifnull(po_det.Stock_Condition,"").trim();
													if(po_stock_cond == "")
													{
														errors.add("• The selected Purchase Order line has no Stock Condition.");
													}
													else if(stock_cond != po_stock_cond)
													{
														errors.add("• Stock Condition must match PO line. PO has: " + po_stock_cond + ".");
