											if(input.Voucher != null || input.Internal_Transfer_Number != null || input.Stock_Return_Number != null || input.Tool_Return_Number != null || input.Transfer_Item != null || input.Item_Issuing_Details != null)
											{
												errors.add("• For Purchase Order, only Purchase Order fields should be filled.");
											}
