										// -----------------------------------------------------
										// INTERNAL TRANSFER
										// -----------------------------------------------------
										else if(rtype == "Internal Transfer")
										{
											if(input.Internal_Transfer_Number == null)
											{
												errors.add("• Internal Transfer Number is required.");
											}
											else if(input.Transfer_Item == null)
											{
												errors.add("• Stock Transfer Item is required.");
											}
											else
											{
												transfer_qty = ifnull(input.Transfer_Item.Quantity,0.0);
												transfer_received_qty = ifnull(input.Transfer_Item.Quantity_Received,0.0);
												transfer_remaining_qty = transfer_qty - transfer_received_qty;
												if(transfer_remaining_qty < 0)
												{
													transfer_remaining_qty = 0.0;
												}
