										if(rtype == "Purchase Order" && po_det != null && po_det.ID != null)
										{
											qty_remaining = ifnull(po_det.Quantity_Remaining,0.0);
											old_qty_this_row = 0.0;
											if(old_rec != null && old_rec.ID != null)
