											}
										}
										is_transfer_return = false;
										if(rtype == "Internal Transfer")
										{
											is_transfer_return = true;
										}
										else if(rtype == "Stock Return")
										{
											is_transfer_return = true;
										}
										else if(rtype == "Tool Return")
										{
											is_transfer_return = true;
										}
										if(is_transfer_return == true && issue_rec != null && issue_rec.ID != null)
										{
											if(ifnull(issue_rec.Status,"") == "Cancelled")
											{
