											}
											issued_qty = ifnull(issue_rec.Quantity,0.0);
											returned_qty = ifnull(issue_rec.Quantity_Returned,0.0);
											remaining_issue_qty = issued_qty - returned_qty;
											if(remaining_issue_qty < 0)
											{
												remaining_issue_qty = 0.0;
											}
											if(remaining_issue_qty <= 0)
											{
												errors.add("• This issuing record has already been fully received.");
											}
											else if(qty_received > remaining_issue_qty)
											{
												errors.add("• You cannot receive more than the remaining issued quantity.");
											}
											if(issue_rec.Unit_Of_Measure != null && input.Unit_Of_Measure_Received != null && input.Unit_Of_Measure_Received != issue_rec.Unit_Of_Measure)
											{
												errors.add("• Unit Of Measure Received must match the issued Unit Of Measure.");
											}
											if(rtype == "Internal Transfer")
											{
												existing_transfer = Stock_Receiving_Details[Receiving_Type == "Internal Transfer" && Transfer_Item == selected_issue_id && ID != input.ID];
												if(existing_transfer.count() > 0)
												{
													errors.add("• This Item Issuing Details record has already been received as an Internal Transfer.");
												}
												if(input.Quantity_to_Receive != null && qty_received != input.Quantity_to_Receive)
												{
													errors.add("• For Internal Transfer, Quantity Received must exactly match Quantity to Receive.");
												}
												source_store = "";
												destination_store_name = "";
												if(issue_rec.Issuing_Voucher != null)
												{
													iss_hdr = Item_Issuing_Voucher[ID == issue_rec.Issuing_Voucher];
													if(iss_hdr.ID != null)
													{
														source_store = ifnull(iss_hdr.Display_Name_Store,"").trim();
													}
												}
												if(srv != null && srv.ID != null)
												{
													destination_store_name = ifnull(srv.Display_Name_Store,"").trim();
												}
												if(source_store == "")
												{
													errors.add("• The source Item Issuing Voucher has no Store.");
												}
												else if(destination_store_name != "" && source_store == destination_store_name)
												{
													errors.add("• Source Store and Destination Store cannot be the same for Internal Transfer.");
												}
											}
											else if(rtype == "Stock Return")
											{
											}
											else if(rtype == "Tool Return")
											{
												if(stock_cond == "New")
												{
													errors.add("• Tool Return cannot be received as New.");
												}
											}
										}
										if(errors.size() > 0)
										{
											msg = "Please fix the following:\n\n";
											for each  err_msg in errors
											{
												msg = msg + err_msg + "\n";
											}
											alert msg;
											cancel submit;
										}

