														next_tax_amount = round(ifnull(next_invoice_rec.Tax_Amount,0.0),2);
														next_amount_paid = round(ifnull(next_invoice_rec.Amount_Paid,0.0),2);
														next_invoice_grand_total = round(next_invoice_sub_total - next_discount_amount + next_tax_amount,2);
														if(next_invoice_grand_total < 0)
